def dfs(graph, start, visited=None):
    if visited is None:
        visited = set()
    visited.add(start)
    result = [start]
    for neighbor in graph.get(start, []):
        if neighbor not in visited:
            result.extend(dfs(graph, neighbor, visited))
    return result

# graph = {'A': ['B', 'C'], 'B': ['D'], 'C': ['D'], 'D': []}
# dfs(graph, 'A') -> ['A', 'B', 'D', 'C']
```

